def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Validate cwd is canonical absolute
    if not cwd.startswith('/') or cwd != cwd.rstrip('/') or '//' in cwd:
        if cwd != '/':
            return None

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty and '.' components
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    # Move to parent
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                next_path = '/' + component
            else:
                next_path = current + '/' + component

            # Check if it's a symlink
            if next_path in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[next_path]

                # Resolve target relative to the directory containing the link
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to directory containing link
                    link_dir = next_path.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'
                    current = link_dir
                    remaining = target

                # Break inner loop to restart with new remaining components
                break
            else:
                current = next_path
        else:
            # All components processed without encountering a symlink
            break

    # Remove trailing slash, except for root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

